SELECT dn.donor_id, u.full_name, dn.region_code, count(d.donation_id)::int AS donation_count, dense_rank() OVER (PARTITION BY dn.region_code ORDER BY count(d.donation_id) DESC) AS rank_in_region FROM donor dn JOIN app_user u ON u.user_id = dn.user_id LEFT JOIN donation d ON d.donor_id = dn.donor_id GROUP BY dn.donor_id, u.full_name, dn.region_code ORDER BY dn.region_code, rank_in_region ASC;
